#!/usr/bin/env bash

peer lifecycle chaincode commit --tls -o ${ORDERER_ADDRESS}:${ORDERER_PORT} --cafile /etc/hyperledger/fabric/orderer/tls/ca.crt --channelID firmware --name firmware-updates-chaincode --version 1.0.0 --sequence 1 --peerAddresses $PEER_ADDRESS:$PEER_PORT --tlsRootCertFiles /etc/hyperledger/fabric/tls/ca.crt --peerAddresses purdue-motor-company-peer0:7151 --tlsRootCertFiles /etc/hyperledger/fabric/purdue-motor-company/tls/ca.crt --signature-policy "OR('NHTSAMSP.member', 'PurdueMotorCompanyMSP.member')"
peer lifecycle chaincode commit --tls -o ${ORDERER_ADDRESS}:${ORDERER_PORT} --cafile /etc/hyperledger/fabric/orderer/tls/ca.crt --channelID fmvss --name fmvss-certification-chaincode --version 1.0.0 --sequence 1 --peerAddresses $PEER_ADDRESS:$PEER_PORT --tlsRootCertFiles /etc/hyperledger/fabric/tls/ca.crt --peerAddresses purdue-motor-company-peer0:7151 --tlsRootCertFiles /etc/hyperledger/fabric/purdue-motor-company/tls/ca.crt --signature-policy "OR('NHTSAMSP.member', 'PurdueMotorCompanyMSP.member')"
peer lifecycle chaincode commit --tls -o ${ORDERER_ADDRESS}:${ORDERER_PORT} --cafile /etc/hyperledger/fabric/orderer/tls/ca.crt --channelID recall --name recall-notifications-chaincode --version 1.0.0 --sequence 1 --peerAddresses $PEER_ADDRESS:$PEER_PORT --tlsRootCertFiles /etc/hyperledger/fabric/tls/ca.crt --peerAddresses purdue-motor-company-peer0:7151 --tlsRootCertFiles /etc/hyperledger/fabric/purdue-motor-company/tls/ca.crt --peerAddresses bess-leasing-company-peer0:7251 --tlsRootCertFiles /etc/hyperledger/fabric/bess-leasing-company/tls/ca.crt --collections-config /chaincode/recall/config/collections_config.json
peer lifecycle chaincode commit --tls -o ${ORDERER_ADDRESS}:${ORDERER_PORT} --cafile /etc/hyperledger/fabric/orderer/tls/ca.crt --channelID vehicle --name vehicle-state-chaincode --version 1.0.0 --sequence 1 --peerAddresses $PEER_ADDRESS:$PEER_PORT --tlsRootCertFiles /etc/hyperledger/fabric/tls/ca.crt --peerAddresses purdue-motor-company-peer0:7151 --tlsRootCertFiles /etc/hyperledger/fabric/purdue-motor-company/tls/ca.crt --collections-config /chaincode/vehicle/config/collections_config.json

